import java.util.HashSet;
import java.util.Set;

class Solution {
    public int getCommon(int[] nums1, int[] nums2) {
        Set<Integer> seen = new HashSet<>();
        for (int value : nums1) {
            seen.add(value);
        }
        for (int value : nums2) {
            if (seen.contains(value)) {
                return value;
            }
        }
        return -1;
    }
}

class Solution {
    public int getCommon(int[] nums1, int[] nums2) {
        int[] candidates = nums1.length <= nums2.length ? nums1 : nums2;
        int[] searched = nums1.length <= nums2.length ? nums2 : nums1;
        for (int value : candidates) {
            if (contains(searched, value)) {
                return value;
            }
        }
        return -1;
    }

    private boolean contains(int[] nums, int target) {
        int left = 0;
        int right = nums.length - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] == target) {
                return true;
            }
            if (nums[mid] < target) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return false;
    }
}

class Solution {
    public int getCommon(int[] nums1, int[] nums2) {
        int i = 0;
        int j = 0;
        while (i < nums1.length && j < nums2.length) {
            if (nums1[i] == nums2[j]) {
                return nums1[i];
            }
            if (nums1[i] < nums2[j]) {
                i = lowerBound(nums1, i + 1, nums2[j]);
            } else {
                j = lowerBound(nums2, j + 1, nums1[i]);
            }
        }
        return -1;
    }

    private int lowerBound(int[] nums, int start, int target) {
        int left = start;
        int right = nums.length;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] < target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }
}
